`timescale 1ns/1ps
// HBM-P4-SPLIT (2026-10-23): CORE-SPLIT twin of the pinned ot_hdc_sinkhorn (rtl/hdc/v41/ot_hdc_sinkhorn.sv), generated by
// physical/die_plan/hbm/over_cap_split/gen_sinkhorn_s.py: the step-0 / steady arithmetic blocks are copied VERBATIM.
// Why: ot_hbm_hc_root_static's two tails (ot_hbm_hc_tail_unit_static, 673k Yosys cells each, never closed) are 84 %
// this unit (567k).  The unit is cut into two hard cores along its dataflow:
//   ot_hdc_sk_step0  : step-0 inputs er, cycle A (row sums, normalise -> A registers), cycle B (divide with gradual
//                      underflow, + eps) -> NEW B output registers b_q (512 b) + registered fault terms;
//   ot_hdc_sk_steady : the matrix st, the steady step (sum, + eps, divide), control, outputs.
// Crossings (all register to register): steady -> step0: load / pa / pb strobes (control flops); step0 -> steady: b_q
// 512 b, bbad_q, abad_q (step-0 registers); in_valid / in_e from the parent land in er (step0) and the control (steady).
// COST: +1 edge: step 0's B result is registered before it enters st (state P_B2); out_valid comes 2 ITERS + 2 edges
// after the accepting edge (42 for ITERS 20, pinned 41); y / fault values are identical.  In the steady state the
// critical loop (st -> step -> st) is unchanged and lives inside one core.
// MUT (bench only): 1 = the B output register captures at P_A (one edge early, stale data) -> must FAIL.
module ot_hdc_sk_step0 #(
    parameter [31:0]  EPS = 32'h358637BD,
    parameter integer MUT = 0
) (
    input  wire         clk,
    input  wire         load,                  // accept edge: er <= in_e
    input  wire [511:0] in_e,
    input  wire         pa, pb,                // control phase flops of ot_hdc_sk_steady
    output reg  [511:0] b_q,
    output reg          bbad_q,
    output reg          abad_q
);
    localparam [7:0]  EPS_E = (EPS[30:23] == 8'd0) ? 8'd1 : EPS[30:23];
    localparam [23:0] EPS_M = {EPS[30:23] != 8'd0, EPS[22:0]};
    reg [31:0] er [0:15];
    reg [23:0]       a_xm [0:15];
    reg signed [9:0] a_xe [0:15];
    reg              a_xz [0:15];
    reg [23:0]       a_tm [0:3];
    reg signed [9:0] a_te [0:3];
    genvar r, c;
    // ======================= step 0, cycle A: row sums, normalise =======================
    wire [15:0] a_bad_in;
    wire [3:0]  a_bad_sum;
    wire [23:0]       nx_m [0:15];
    wire signed [9:0] nx_e [0:15];
    wire              nx_z [0:15];
    wire [23:0]       nt_m [0:3];
    wire signed [9:0] nt_e [0:3];
    generate
        for (r = 0; r < 16; r = r + 1) begin : g_ain
            wire [31:0] w = er[r];
            assign a_bad_in[r] = (w[31] && (w[30:0] != 31'd0)) || (w[30:23] == 8'hFF);
            ot_hdc_sk_norm u_nx (.x(w[30:0]), .m(nx_m[r]), .e(nx_e[r]), .z(nx_z[r]));
        end
        for (r = 0; r < 4; r = r + 1) begin : g_arow
            wire [7:0]  ee [0:3];
            wire [23:0] mm [0:3];
            for (c = 0; c < 4; c = c + 1) begin : g_dec
                wire [31:0] w = er[4*r + c];
                assign ee[c] = (w[30:23] == 8'd0) ? 8'd1 : w[30:23];
                assign mm[c] = {w[30:23] != 8'd0, w[22:0]};
            end
            wire [7:0] e1, e2, e3, g1, g2, g3;
            wire [23:0] m1, m2, m3;
            wire o1, o2, o3, u1, u2, u3, tz;
            ot_hdc_sk_add u_a1 (.ea(ee[0]), .ua(1'b0), .ma(mm[0]), .eb(ee[1]), .mb(mm[1]),
                                .eg(g1), .up(u1), .e(e1), .m(m1), .ovf(o1));
            ot_hdc_sk_add u_a2 (.ea(g1), .ua(u1), .ma(m1), .eb(ee[2]), .mb(mm[2]),
                                .eg(g2), .up(u2), .e(e2), .m(m2), .ovf(o2));
            ot_hdc_sk_add u_a3 (.ea(g2), .ua(u2), .ma(m2), .eb(ee[3]), .mb(mm[3]),
                                .eg(g3), .up(u3), .e(e3), .m(m3), .ovf(o3));
            wire [30:0] sum = {m3[23] ? e3 : 8'd0, m3[22:0]};
            ot_hdc_sk_norm u_nt (.x(sum), .m(nt_m[r]), .e(nt_e[r]), .z(tz));
            assign a_bad_sum[r] = o1 | o2 | o3 | tz;
        end
    endgenerate


    // ======================= step 0, cycle B: divide with underflow, + eps ==============
    wire [31:0] b_out [0:15];
    wire [15:0] b_bad;
    generate
        for (r = 0; r < 4; r = r + 1) begin : g_brow
            wire [28:0] rs;
            ot_hdc_sk_seed u_seed (.tm(a_tm[r]), .r(rs));
            for (c = 0; c < 4; c = c + 1) begin : g_bel
                wire [30:0] q;
                wire rng, ov;
                ot_hdc_sk_quot #(.SUBN(1)) u_q (.xm(a_xm[4*r + c]), .xe(a_xe[4*r + c]), .xz(a_xz[4*r + c]),
                                                .tm(a_tm[r]), .te(a_te[r]), .r(rs), .y(q), .range(rng));
                wire [7:0]  qe = (q[30:23] == 8'd0) ? 8'd1 : q[30:23];
                wire [23:0] qm = {q[30:23] != 8'd0, q[22:0]};
                wire [7:0]  oe, og;
                wire [23:0] om;
                wire        ou;
                ot_hdc_sk_add u_eps (.ea(qe), .ua(1'b0), .ma(qm), .eb(EPS_E), .mb(EPS_M),
                                     .eg(og), .up(ou), .e(oe), .m(om), .ovf(ov));
                // transposed write: storage row c holds logical column c
                assign b_out[4*c + r] = {1'b0, om[23] ? oe : 8'd0, om[22:0]};
                assign b_bad[4*r + c] = rng | ov;
            end
        end
    endgenerate


    integer k;
    always @(posedge clk) begin
        for (k = 0; k < 16; k = k + 1) begin
            if (load) er[k] <= in_e[32*k +: 32];
            if (pa) begin
                a_xm[k] <= nx_m[k];
                a_xe[k] <= nx_e[k];
                a_xz[k] <= nx_z[k];
            end
            if ((MUT == 1) ? pa : pb) b_q[32*k +: 32] <= b_out[k];
        end
        for (k = 0; k < 4; k = k + 1) if (pa) begin
            a_tm[k] <= nt_m[k];
            a_te[k] <= nt_e[k];
        end
        if (pa) abad_q <= (|a_bad_in) | (|a_bad_sum);
        if (pb) bbad_q <= |b_bad;
    end
endmodule

module ot_hdc_sk_steady #(
    parameter integer ITERS = 20,
    parameter [31:0]  EPS = 32'h358637BD
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         in_valid,
    output wire         in_ready,
    output wire         load, pa, pb,
    input  wire [511:0] b_q,
    input  wire         bbad_q,
    input  wire         abad_q,
    output reg          out_valid,
    output wire [511:0] y,
    output reg          fault,
    output wire         busy
);
    localparam integer STEPS = 2 * ITERS - 1;
    localparam [2:0] P_IDLE = 3'd0, P_A = 3'd1, P_B = 3'd2, P_B2 = 3'd3, P_RUN = 3'd4;
    localparam [7:0]  EPS_E = (EPS[30:23] == 8'd0) ? 8'd1 : EPS[30:23];
    localparam [23:0] EPS_M = {EPS[30:23] != 8'd0, EPS[22:0]};
    reg [2:0]  ph;
    reg        r_pa, r_pb;                     // phase strobes as flops (step0 core pins)
    reg [7:0]  cnt;
    reg        flt;
    reg [31:0] st [0:15];
    assign in_ready = (ph == P_IDLE);
    assign busy = (ph != P_IDLE);
    assign load = in_ready && in_valid;
    assign pa = r_pa; assign pb = r_pb;
    genvar r, c;
    // ======================= steady step: sum, + eps, divide ============================
    wire [31:0] s_out [0:15];
    wire [15:0] s_bad;
    generate
        for (r = 0; r < 4; r = r + 1) begin : g_srow
            wire [7:0]  ee [0:3];
            wire [23:0] mm [0:3];
            wire [3:0]  sub;
            for (c = 0; c < 4; c = c + 1) begin : g_dec
                wire [31:0] w = st[4*r + c];
                assign ee[c]  = (w[30:23] == 8'd0) ? 8'd1 : w[30:23];
                assign mm[c]  = {w[30:23] != 8'd0, w[22:0]};
                assign sub[c] = (w[30:23] == 8'd0);
            end
            wire [7:0] e1, e2, e3, et, g1, g2, g3, gt;
            wire [23:0] m1, m2, m3, mt;
            wire o1, o2, o3, ot, u1, u2, u3, ut;
            // the chain: each add takes the previous one's exponent as eg + up (up resolves last)
            ot_hdc_sk_add u_s1 (.ea(ee[0]), .ua(1'b0), .ma(mm[0]), .eb(ee[1]), .mb(mm[1]),
                                .eg(g1), .up(u1), .e(e1), .m(m1), .ovf(o1));
            ot_hdc_sk_add u_s2 (.ea(g1), .ua(u1), .ma(m1), .eb(ee[2]), .mb(mm[2]),
                                .eg(g2), .up(u2), .e(e2), .m(m2), .ovf(o2));
            ot_hdc_sk_add u_s3 (.ea(g2), .ua(u2), .ma(m2), .eb(ee[3]), .mb(mm[3]),
                                .eg(g3), .up(u3), .e(e3), .m(m3), .ovf(o3));
            ot_hdc_sk_add u_ae (.ea(g3), .ua(u3), .ma(m3), .eb(EPS_E), .mb(EPS_M),
                                .eg(gt), .up(ut), .e(et), .m(mt), .ovf(ot));
            // t >= eps is normal: its significand is already normalised
            wire signed [9:0] te = $signed({2'b00, et}) - 10'sd127;
            wire [28:0] rs;
            ot_hdc_sk_seed u_seed (.tm(mt), .r(rs));
            for (c = 0; c < 4; c = c + 1) begin : g_sel
                wire [30:0] q;
                wire rng;
                ot_hdc_sk_quot #(.SUBN(0)) u_q (.xm(mm[c]), .xe($signed({2'b00, ee[c]}) - 10'sd127), .xz(1'b0),
                                                .tm(mt), .te(te), .r(rs), .y(q), .range(rng));
                assign s_out[4*c + r] = {1'b0, q};
                assign s_bad[4*r + c] = rng | sub[c] | o1 | o2 | o3 | ot | !mt[23];
            end
        end
    endgenerate


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ph <= P_IDLE; r_pa <= 1'b0; r_pb <= 1'b0;
            cnt <= 8'd0;
            flt <= 1'b0;
            out_valid <= 1'b0;
            fault <= 1'b0;
        end else begin
            out_valid <= 1'b0;
            r_pa <= 1'b0; r_pb <= 1'b0;
            case (ph)
                P_IDLE: if (in_valid) begin
                    ph <= P_A; r_pa <= 1'b1;
                    flt <= 1'b0;
                end
                P_A: begin
                    ph <= P_B; r_pb <= 1'b1;
                end
                P_B: begin
                    ph <= P_B2;
                    flt <= flt | abad_q;
                end
                P_B2: begin
                    flt <= flt | bbad_q;
                    cnt <= STEPS[7:0];
                    if (STEPS == 0) begin
                        ph <= P_IDLE;
                        out_valid <= 1'b1;
                        fault <= flt | bbad_q;
                    end else ph <= P_RUN;
                end
                default: begin
                    flt <= flt | (|s_bad);
                    cnt <= cnt - 8'd1;
                    if (cnt == 8'd1) begin
                        ph <= P_IDLE;
                        out_valid <= 1'b1;
                        fault <= flt | (|s_bad);
                    end
                end
            endcase
        end
    end
    integer k;
    always @(posedge clk) begin
        for (k = 0; k < 16; k = k + 1) begin
            if (ph == P_B2) st[k] <= b_q[32*k +: 32];
            else if (ph == P_RUN) st[k] <= s_out[k];
        end
    end
    generate
        for (r = 0; r < 16; r = r + 1) begin : g_y
            assign y[32*r +: 32] = fault ? 32'd0 : st[r];
        end
    endgenerate
endmodule

module ot_hdc_sinkhorn_s #(
    parameter integer ITERS = 20,
    parameter [31:0]  EPS = 32'h358637BD,
    parameter integer MUT = 0
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [511:0] in_e,
    output wire         out_valid,
    output wire [511:0] y,
    output wire         fault,
    output wire         busy
);
    wire load, pa, pb, bbad_q, abad_q; wire [511:0] b_q;
    ot_hdc_sk_step0 #(.EPS(EPS), .MUT(MUT)) u_s0 (.clk(clk), .load(load), .in_e(in_e), .pa(pa), .pb(pb),
        .b_q(b_q), .bbad_q(bbad_q), .abad_q(abad_q));
    ot_hdc_sk_steady #(.ITERS(ITERS), .EPS(EPS)) u_ss (.clk(clk), .rst_n(rst_n), .in_valid(in_valid), .in_ready(in_ready),
        .load(load), .pa(pa), .pb(pb), .b_q(b_q), .bbad_q(bbad_q), .abad_q(abad_q),
        .out_valid(out_valid), .y(y), .fault(fault), .busy(busy));
endmodule
